// PLAN:
// 1. Setup & CSS Variables: Inject a <style> tag with Northeastern University design system tokens (colors, typography, spacing).
// 2. Seed Data: Define realistic UserSkills (e.g., Python, Data Analysis) and TargetRoles (e.g., Data Scientist, Product Manager) with required skill levels.
// 3. State Management: 
//    - `currentView`: 'dashboard' | 'loading_analysis' | 'analysis'
//    - `selectedRole`: TargetRole object
//    - `selectedSkill`: Skill object (triggers modal)
// 4. Components:
//    - `App`: Root component, holds state and layout.
//    - `DemoControls`: Top-right panel for forcing state transitions (testing).
//    - `TargetSelectionDashboard`: Grid of role cards, profile summary, and search bar.
//    - `RoleCard`: Interactive card with hover/active states and keyboard accessibility.
//    - `GapAnalysisVisualization`: Core view showing match %, gap map, and categorized skill lists.
//    - `MatchPercentageRing`: SVG animated ring (typographic mass motion contract).
//    - `SkillNode`: Individual skill pill with hover tooltip, status colors, and layoutId for spatial extension.
//    - `SkillActionDetailModal`: Framer Motion AnimatePresence overlay.
// 5. AI Integration:
//    - In `SkillActionDetailModal`, when a missing/partial skill is clicked, fetch real recommendations from `/api/ai/gemini-compat`.
// 6. Motion Contract:
//    - Staggered entrance for skill nodes in GapAnalysisVisualization.
//    - Spatial extension (layout animation) for the modal.
//    - Color modulation for skill status (Possessed=Cool/Muted, Missing=Warm/Active).

const {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
  Fragment
} = React;

const {
  motion,
  AnimatePresence,
  useAnimation
} = window.framerMotion;

// --- SEED DATA ---
const USER_SKILLS = {
  'python': { name: 'Python', level: 3, category: 'Hard Skills' },
  'sql': { name: 'SQL', level: 4, category: 'Hard Skills' },
  'data_viz': { name: 'Data Visualization', level: 2, category: 'Hard Skills' },
  'comm': { name: 'Communication', level: 4, category: 'Soft Skills' },
  'agile': { name: 'Agile Methodology', level: 2, category: 'Process' },
  'git': { name: 'Git/Version Control', level: 3, category: 'Tools' }
};

const TARGET_ROLES = [
  {
    id: 'data_scientist',
    title: 'Data Scientist',
    description: 'Analyze complex data to help guide decision-making.',
    requirements: {
      'python': 4,
      'sql': 4,
      'data_viz': 4,
      'ml': 3, // Missing
      'stats': 4, // Missing
      'comm': 4
    }
  },
  {
    id: 'product_manager',
    title: 'Product Manager',
    description: 'Lead cross-functional teams to deliver product features.',
    requirements: {
      'agile': 4,
      'comm': 5,
      'sql': 2,
      'user_research': 3, // Missing
      'roadmapping': 4 // Missing
    }
  },
  {
    id: 'data_engineer',
    title: 'Data Engineer',
    description: 'Build systems that collect, manage, and convert raw data.',
    requirements: {
      'python': 4,
      'sql': 5,
      'git': 4,
      'cloud_aws': 3, // Missing
      'etl_pipelines': 4 // Missing
    }
  }
];

const SKILL_DICTIONARY = {
  'python': { name: 'Python', category: 'Hard Skills' },
  'sql': { name: 'SQL', category: 'Hard Skills' },
  'data_viz': { name: 'Data Visualization', category: 'Hard Skills' },
  'ml': { name: 'Machine Learning', category: 'Hard Skills' },
  'stats': { name: 'Statistical Modeling', category: 'Hard Skills' },
  'comm': { name: 'Communication', category: 'Soft Skills' },
  'agile': { name: 'Agile Methodology', category: 'Process' },
  'git': { name: 'Git/Version Control', category: 'Tools' },
  'user_research': { name: 'User Research', category: 'Process' },
  'roadmapping': { name: 'Product Roadmapping', category: 'Process' },
  'cloud_aws': { name: 'Cloud Computing (AWS)', category: 'Tools' },
  'etl_pipelines': { name: 'ETL Pipelines', category: 'Hard Skills' }
};

// --- UTILS ---
const calculateGap = (role) => {
  let totalReqs = 0;
  let metReqs = 0;
  const categorized = { possessed: [], partial: [], missing: [] };

  Object.entries(role.requirements).forEach(([skillId, reqLevel]) => {
    totalReqs += reqLevel;
    const userSkill = USER_SKILLS[skillId];
    const skillInfo = SKILL_DICTIONARY[skillId];

    if (!userSkill) {
      categorized.missing.push({ id: skillId, ...skillInfo, currentLevel: 0, requiredLevel: reqLevel, status: 'missing' });
    } else if (userSkill.level >= reqLevel) {
      metReqs += reqLevel;
      categorized.possessed.push({ id: skillId, ...skillInfo, currentLevel: userSkill.level, requiredLevel: reqLevel, status: 'possessed' });
    } else {
      metReqs += userSkill.level;
      categorized.partial.push({ id: skillId, ...skillInfo, currentLevel: userSkill.level, requiredLevel: reqLevel, status: 'partial' });
    }
  });

  const matchPercentage = Math.round((metReqs / totalReqs) * 100);
  return { matchPercentage, categorized };
};

// --- STYLES ---
