// PLAN:
// 1. Setup & CSS Variables: Inject a <style> tag with Northeastern University design system tokens (colors, typography, spacing).
// 2. Seed Data: Define realistic UserSkills (e.g., Python, Data Analysis) and TargetRoles (e.g., Data Scientist, Product Manager) with required skill levels.
// 3. State Management: 
//    - `currentView`: 'dashboard' | 'loading_analysis' | 'analysis'
//    - `selectedRole`: TargetRole object
//    - `selectedSkill`: Skill object (triggers modal)
// 4. Components:
//    - `App`: Root component, holds state and layout.
//    - `DemoControls`: Top-right panel for forcing state transitions (testing).
//    - `TargetSelectionDashboard`: Grid of role cards, profile summary, and search bar.
//    - `RoleCard`: Interactive card with hover/active states and keyboard accessibility.
//    - `GapAnalysisVisualization`: Core view showing match %, gap map, and categorized skill lists.
//    - `MatchPercentageRing`: SVG animated ring (typographic mass motion contract).
//    - `SkillNode`: Individual skill pill with hover tooltip, status colors, and layoutId for spatial extension.
//    - `SkillActionDetailModal`: Framer Motion AnimatePresence overlay.
// 5. AI Integration:
//    - In `SkillActionDetailModal`, when a missing/partial skill is clicked, fetch real recommendations from `/api/ai/gemini-compat`.
// 6. Motion Contract:
//    - Staggered entrance for skill nodes in GapAnalysisVisualization.
//    - Spatial extension (layout animation) for the modal.
//    - Color modulation for skill status (Possessed=Cool/Muted, Missing=Warm/Active).

const {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
  Fragment
} = React;

const {
  motion,
  AnimatePresence,
  useAnimation
} = window.framerMotion;

// --- SEED DATA ---
const USER_SKILLS = {
  'python': { name: 'Python', level: 3, category: 'Hard Skills' },
  'sql': { name: 'SQL', level: 4, category: 'Hard Skills' },
  'data_viz': { name: 'Data Visualization', level: 2, category: 'Hard Skills' },
  'comm': { name: 'Communication', level: 4, category: 'Soft Skills' },
