};

const TARGET_ROLES = [
  {
    id: 'data_scientist',
    title: 'Data Scientist',
    description: 'Analyze complex data to help guide decision-making.',
    requirements: {
      'python': 4,
      'sql': 4,
      'data_viz': 4,
      'ml': 3, // Missing
      'stats': 4, // Missing
      'comm': 4
    }
  },
