      'sql': 5,
      'git': 4,
      'cloud_aws': 3, // Missing
      'etl_pipelines': 4 // Missing
    }
  }
];

const SKILL_DICTIONARY = {
  'python': { name: 'Python', category: 'Hard Skills' },
  'sql': { name: 'SQL', category: 'Hard Skills' },
  'data_viz': { name: 'Data Visualization', category: 'Hard Skills' },
  'ml': { name: 'Machine Learning', category: 'Hard Skills' },
  'stats': { name: 'Statistical Modeling', category: 'Hard Skills' },
  'comm': { name: 'Communication', category: 'Soft Skills' },
  'agile': { name: 'Agile Methodology', category: 'Process' },
  'git': { name: 'Git/Version Control', category: 'Tools' },
  'user_research': { name: 'User Research', category: 'Process' },
  'roadmapping': { name: 'Product Roadmapping', category: 'Process' },
  'cloud_aws': { name: 'Cloud Computing (AWS)', category: 'Tools' },
  'etl_pipelines': { name: 'ETL Pipelines', category: 'Hard Skills' }
};

// --- UTILS ---
const calculateGap = (role) => {
  let totalReqs = 0;
  let metReqs = 0;
  const categorized = { possessed: [], partial: [], missing: [] };

  Object.entries(role.requirements).forEach(([skillId, reqLevel]) => {
    totalReqs += reqLevel;
    const userSkill = USER_SKILLS[skillId];
    const skillInfo = SKILL_DICTIONARY[skillId];

    if (!userSkill) {
      categorized.missing.push({ id: skillId, ...skillInfo, currentLevel: 0, requiredLevel: reqLevel, status: 'missing' });
    } else if (userSkill.level >= reqLevel) {
      metReqs += reqLevel;
      categorized.possessed.push({ id: skillId, ...skillInfo, currentLevel: userSkill.level, requiredLevel: reqLevel, status: 'possessed' });
    } else {
      metReqs += userSkill.level;
      categorized.partial.push({ id: skillId, ...skillInfo, currentLevel: userSkill.level, requiredLevel: reqLevel, status: 'partial' });
    }
  });

  const matchPercentage = Math.round((metReqs / totalReqs) * 100);
  return { matchPercentage, categorized };
};

