              <div style={{ position: 'absolute', inset: 0, zIndex: 1, background: 'rgba(255,255,255,0.8)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div className="shimmer" style={{ width: '100%', height: '100%', position: 'absolute', opacity: 0.5 }} />
                <span className="label" style={{ position: 'relative', zIndex: 2, color: 'var(--color-nu-red)' }}>Calculating Match...</span>
              </div>
            )}
            <h3 style={{ marginBottom: 'var(--space-2)' }}>{role.title}</h3>
            <p style={{ color: 'var(--color-text-secondary)', fontSize: 14, marginBottom: 'var(--space-4)' }}>{role.description}</p>
            <div style={{ display: 'flex', gap: 'var(--space-2)', flexWrap: 'wrap' }}>
              {Object.keys(role.requirements).slice(0, 3).map(req => (
                <span key={req} style={{ fontSize: 12, background: 'var(--color-surface)', padding: '2px 8px', borderRadius: 12, border: '1px solid var(--color-border)' }}>
                  {SKILL_DICTIONARY[req]?.name || req}
                </span>
              ))}
              {Object.keys(role.requirements).length > 3 && <span style={{ fontSize: 12, color: 'var(--color-text-secondary)', alignSelf: 'center' }}>+{Object.keys(role.requirements).length - 3} more</span>}
            </div>
          </div>
        ))}
        {filteredRoles.length === 0 && (
          <p style={{ color: 'var(--color-text-secondary)' }}>No roles found matching your search.</p>
        )}
      </div>
    </motion.div>
  );
};

const MatchPercentageRing = ({ percentage }) => {
  const radius = 60;
  const stroke = 12;
  const normalizedRadius = radius - stroke * 2;
  const circumference = normalizedRadius * 2 * Math.PI;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  // Color logic based on threshold
  const getColor = (p) => {
    if (p >= 80) return 'var(--color-success)';
    if (p >= 50) return 'var(--color-warning)';
    return 'var(--color-friction)';
  };

  return (
    <div style={{ position: 'relative', width: radius * 2, height: radius * 2, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <svg height={radius * 2} width={radius * 2} style={{ transform: 'rotate(-90deg)' }}>
        <circle
          stroke="var(--color-border)"
          fill="transparent"
          strokeWidth={stroke}
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />
        <motion.circle
          stroke={getColor(percentage)}
          fill="transparent"
          strokeWidth={stroke}
          strokeDasharray={circumference + ' ' + circumference}
          style={{ strokeDashoffset: circumference }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1.5, ease: "easeOut", delay: 0.2 }}
          strokeLinecap="round"
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />
      </svg>
      <div style={{ position: 'absolute', textAlign: 'center' }}>
        <motion.div 
          initial={{ scale: 0.8, opacity: 0, fontWeight: 400 }}
          animate={{ scale: 1, opacity: 1, fontWeight: 700 }}
          transition={{ delay: 1.2, duration: 0.4 }}
          style={{ fontFamily: 'var(--font-display)', fontSize: 36, lineHeight: 1, color: getColor(percentage) }}
        >
          {percentage}%
        </motion.div>
        <div className="label" style={{ fontSize: 10, color: 'var(--color-text-secondary)' }}>Match</div>
      </div>
    </div>
  );
};

const SkillNode = ({ skill, onClick }) => {
  const isPossessed = skill.status === 'possessed';
  const isPartial = skill.status === 'partial';
  const isMissing = skill.status === 'missing';

  let bgColor, borderColor, icon, textColor;

  // Motion Contract: Color Modulation
  if (isPossessed) {
    bgColor = '#E6F9F0'; // Muted cool tone
    borderColor = 'var(--color-success)';
    textColor = '#0A5C30';
    icon = <window.lucide.CheckCircle2 size={16} color={borderColor} />;
  } else if (isPartial) {
    bgColor = '#FFF4EB';
    borderColor = 'var(--color-warning)';
    textColor = '#8A4D00';
    icon = <window.lucide.ArrowUpCircle size={16} color={borderColor} />;
  } else {
    bgColor = '#FDEAEA'; // Active warm tone
    borderColor = 'var(--color-friction)';
    textColor = 'var(--color-nu-dark-red)';
    icon = <window.lucide.PlusCircle size={16} color={borderColor} />;
  }

  return (
    <motion.div
      layoutId={`skill-${skill.id}`}
      variants={{
        hidden: { opacity: 0, y: 10 },
        visible: { opacity: 1, y: 0 }
      }}
      className={`tooltip-container ${!isPossessed ? 'card-interactive' : ''}`}
      onClick={() => !isPossessed && onClick(skill)}
      role={!isPossessed ? "button" : "status"}
      tabIndex={!isPossessed ? 0 : undefined}
      onKeyDown={(e) => !isPossessed && e.key === 'Enter' && onClick(skill)}
      style={{
        display: 'flex', alignItems: 'center', gap: 'var(--space-2)',
        padding: 'var(--space-2) var(--space-3)',
        background: bgColor, border: `1px solid ${borderColor}`,
        borderRadius: 24, cursor: isPossessed ? 'default' : 'pointer',
        width: 'fit-content',
        outline: 'none'
      }}
      whileHover={!isPossessed ? { scale: 1.02, boxShadow: `0 0 0 1px ${borderColor}` } : {}}
      whileTap={!isPossessed ? { scale: 0.98 } : {}}
    >
      {icon}
      <span style={{ fontWeight: 600, color: textColor, fontSize: 14 }}>{skill.name}</span>
      <div className="tooltip">
        Lvl {skill.currentLevel} / {skill.requiredLevel} Req
      </div>
    </motion.div>
  );
};

const GapAnalysisVisualization = ({ role, onBack, onSkillClick }) => {
  const { matchPercentage, categorized } = useMemo(() => calculateGap(role), [role]);

  const skillsByCategory = useMemo(() => {
    const cats = {};
    Object.entries(role.requirements).forEach(([skillId, reqLevel]) => {
      const skillInfo = SKILL_DICTIONARY[skillId];
      const cat = skillInfo.category;
      if (!cats[cat]) cats[cat] = [];

      const userSkill = USER_SKILLS[skillId];
      let status = 'missing';
      if (userSkill) {
        status = userSkill.level >= reqLevel ? 'possessed' : 'partial';
      }

      cats[cat].push({ id: skillId, ...skillInfo, requiredLevel: reqLevel, currentLevel: userSkill ? userSkill.level : 0, status });
    });
    return cats;
  }, [role]);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.1, delayChildren: 0.3 }
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ padding: 'var(--space-6)', maxWidth: 1200, margin: '0 auto' }}
    >
      <button className="btn btn-ghost" onClick={onBack} style={{ marginBottom: 'var(--space-4)' }}>
        <window.lucide.ArrowLeft size={16} /> Back to Roles
      </button>

      <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-6)', marginBottom: 'var(--space-6)', background: 'white' }}>
        <MatchPercentageRing percentage={matchPercentage} />
        <div>
          <h1 style={{ marginBottom: 'var(--space-1)' }}>{role.title}</h1>
          <p style={{ color: 'var(--color-text-secondary)', fontSize: 16 }}>Gap Analysis Report</p>
        </div>
      </div>

      {/* Visual Gap Map */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: 'var(--space-6)' }}>

        {/* Possessed Skills */}
        <motion.div variants={containerVariants} initial="hidden" animate="visible">
          <h3 style={{ borderBottom: '2px solid var(--color-border)', paddingBottom: 'var(--space-2)', marginBottom: 'var(--space-4)', display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
            <window.lucide.CheckCircle2 size={20} color="var(--color-success)" /> Possessed
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {categorized.possessed.map(skill => <SkillNode key={skill.id} skill={skill} onClick={onSkillClick} />)}
            {categorized.possessed.length === 0 && <p style={{ color: 'var(--color-text-secondary)', fontStyle: 'italic' }}>None identified.</p>}
          </div>
        </motion.div>

        {/* Partial Skills */}
        <motion.div variants={containerVariants} initial="hidden" animate="visible">
          <h3 style={{ borderBottom: '2px solid var(--color-border)', paddingBottom: 'var(--space-2)', marginBottom: 'var(--space-4)', display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
            <window.lucide.ArrowUpCircle size={20} color="var(--color-warning)" /> Needs Level-up
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {categorized.partial.map(skill => <SkillNode key={skill.id} skill={skill} onClick={onSkillClick} />)}
            {categorized.partial.length === 0 && <p style={{ color: 'var(--color-text-secondary)', fontStyle: 'italic' }}>None identified.</p>}
          </div>
        </motion.div>

        {/* Missing Skills */}
        <motion.div variants={containerVariants} initial="hidden" animate="visible">
          <h3 style={{ borderBottom: '2px solid var(--color-border)', paddingBottom: 'var(--space-2)', marginBottom: 'var(--space-4)', display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
            <window.lucide.PlusCircle size={20} color="var(--color-friction)" /> Missing
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {categorized.missing.map(skill => <SkillNode key={skill.id} skill={skill} onClick={onSkillClick} />)}
            {categorized.missing.length === 0 && <p style={{ color: 'var(--color-text-secondary)', fontStyle: 'italic' }}>None identified.</p>}
          </div>
        </motion.div>

      </div>

      {/* Categorized Skill Lists */}
      <div style={{ marginTop: 'var(--space-7)' }}>
        <h2 style={{ marginBottom: 'var(--space-4)' }}>Skills by Category</h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: 'var(--space-4)' }}>
          {Object.entries(skillsByCategory).map(([category, skills]) => (
            <div key={category} className="card">
              <h3 style={{ fontSize: 20, marginBottom: 'var(--space-3)', borderBottom: '1px solid var(--color-border)', paddingBottom: 'var(--space-2)' }}>{category}</h3>
              <ul style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
                {skills.map(skill => (
                  <li key={skill.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: 14 }}>
                    <span style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                      {skill.status === 'possessed' && <window.lucide.CheckCircle2 size={14} color="var(--color-success)" />}
                      {skill.status === 'partial' && <window.lucide.ArrowUpCircle size={14} color="var(--color-warning)" />}
                      {skill.status === 'missing' && <window.lucide.PlusCircle size={14} color="var(--color-friction)" />}
                      {skill.name}
                    </span>
                    <span className="data" style={{ color: 'var(--color-text-secondary)' }}>Lvl {skill.requiredLevel}</span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </motion.div>
  );
};

const SkillActionDetailModal = ({ skill, role, onClose }) => {
  const [recommendations, setRecommendations] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true;
    const fetchAI = async () => {
      setIsLoading(true);
      try {
        const prompt = `
          You are an academic and career advisor at Northeastern University.
          A student is analyzing their skills gap for the role of "${role.title}".
          They need to improve their skill in "${skill.name}".
          Their current proficiency is ${skill.currentLevel}/5. The required proficiency is ${skill.requiredLevel}/5.

          Provide exactly 3 actionable recommendations to bridge this gap. Format as a JSON array of objects with 'type' (e.g., "Course", "Project", "Mentorship") and 'description' (1-2 sentences).
          Keep the tone institutional, plain-spoken, and student-first.

          Example output:
          [
            {"type": "Course", "description": "Enroll in CS5000 to build foundational knowledge."},
            {"type": "Project", "description": "Build a small web scraper to practice data collection."}
          ]
        `;

        const res = await fetch('/api/ai/gemini-compat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
          body: JSON.stringify({
            model: 'gemini-3.1-pro-preview',
            messages: [
              { role: 'system', content: 'You output only valid JSON arrays.' },
              { role: 'user', content: prompt }
            ],
            temperature: 0.3,
            max_tokens: 500,
          }),
        });

        const data = await res.json();
        const content = data?.choices?.[0]?.message?.content;

        if (isMounted) {
          if (content) {
            try {
              // Clean potential markdown formatting from AI response
              const cleanContent = content.replace(/```json/g, '').replace(/```/g, '').trim();
              setRecommendations(JSON.parse(cleanContent));
            } catch (e) {
              console.error("Failed to parse AI JSON", e, content);
              setError("Failed to parse recommendations.");
            }
          } else {
            setError("No response from advisor.");
          }
          setIsLoading(false);
        }
      } catch (err) {
        if (isMounted) {
          console.error(err);
          setError("Failed to connect to advisor.");
          setIsLoading(false);
        }
      }
    };

    fetchAI();
    return () => { isMounted = false; };
  }, [skill, role]);

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 50, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 'var(--space-4)' }}>
      <motion.div 
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }}
        onClick={onClose}
      />
      <motion.div 
        layoutId={`skill-${skill.id}`} // Spatial extension motion contract
        initial={{ opacity: 0, scale: 0.9, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.9, y: 20 }}
        transition={{ type: 'spring', damping: 25, stiffness: 300 }}
        className="card"
        style={{ position: 'relative', zIndex: 51, width: '100%', maxWidth: 600, background: 'var(--color-bg)', boxShadow: '0 24px 48px rgba(0,0,0,0.2)' }}
      >
        <button onClick={onClose} aria-label="Close modal" style={{ position: 'absolute', top: 16, right: 16, background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-secondary)' }}>
          <window.lucide.X size={24} />
        </button>

        <div style={{ marginBottom: 'var(--space-4)' }}>
          <div className="label" style={{ color: 'var(--color-nu-red)', marginBottom: 'var(--space-1)' }}>Action Plan</div>
          <h2>{skill.name}</h2>
          <div style={{ display: 'flex', gap: 'var(--space-4)', marginTop: 'var(--space-2)', fontFamily: 'var(--font-data)', fontSize: 14, color: 'var(--color-text-secondary)' }}>
            <span>Current: Lvl {skill.currentLevel}</span>
            <span>Target: Lvl {skill.requiredLevel}</span>
          </div>
        </div>

        <div style={{ minHeight: 200 }}>
          {isLoading ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
              <div className="shimmer" style={{ height: 60, borderRadius: 8 }} />
              <div className="shimmer" style={{ height: 60, borderRadius: 8 }} />
              <div className="shimmer" style={{ height: 60, borderRadius: 8 }} />
              <p style={{ textAlign: 'center', color: 'var(--color-text-secondary)', fontSize: 14, marginTop: 'var(--space-2)' }}>
                <window.lucide.Sparkles size={14} style={{ display: 'inline', verticalAlign: 'middle', marginRight: 4 }} />
                Generating personalized recommendations...
              </p>
            </div>
          ) : error ? (
            <div style={{ padding: 'var(--space-4)', background: '#FDEAEA', color: 'var(--color-nu-dark-red)', borderRadius: 8 }}>
              {error}
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
              {recommendations?.map((rec, idx) => (
                <motion.div 
                  key={idx}
                  initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: idx * 0.1 }}
                  style={{ padding: 'var(--space-3)', border: '1px solid var(--color-border)', borderRadius: 8, display: 'flex', gap: 'var(--space-3)' }}
                >
                  <div style={{ color: 'var(--color-nu-red)', paddingTop: 2 }}>
                    {rec.type.toLowerCase().includes('course') ? <window.lucide.BookOpen size={20} /> : 
                     rec.type.toLowerCase().includes('project') ? <window.lucide.Code size={20} /> : 
                     <window.lucide.Users size={20} />}
                  </div>
                  <div>
                    <div className="label" style={{ marginBottom: 4 }}>{rec.type}</div>
                    <p style={{ fontSize: 14, color: 'var(--color-text-secondary)' }}>{rec.description}</p>
                  </div>
                </motion.div>
              ))}
            </div>
          )}
        </div>

        <div style={{ marginTop: 'var(--space-5)', display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-3)' }}>
          <button className="btn btn-ghost" onClick={onClose}>Close</button>
          <button className="btn btn-primary" disabled={isLoading}>Save to Learning Path</button>
        </div>
      </motion.div>
    </div>
  );
};

// --- ROOT APP ---
const App = () => {
  const [view, setView] = useState('dashboard'); // 'dashboard', 'analysis'
  const [selectedRole, setSelectedRole] = useState(null);
  const [selectedSkill, setSelectedSkill] = useState(null);

  const handleSelectRole = (role) => {
    setSelectedRole(role);
    setView('analysis');
  };

  const handleBackToDashboard = () => {
    setView('dashboard');
    setSelectedRole(null);
    setSelectedSkill(null);
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <DesignSystemStyles />
      <DemoControls setView={setView} setRole={setSelectedRole} />
      <Header />

      <main style={{ flex: 1, position: 'relative' }}>
        <AnimatePresence mode="wait">
          {view === 'dashboard' && (
            <TargetSelectionDashboard key="dashboard" onSelectRole={handleSelectRole} />
          )}
          {view === 'analysis' && selectedRole && (
            <GapAnalysisVisualization 
              key="analysis" 
              role={selectedRole} 
              onBack={handleBackToDashboard}
              onSkillClick={setSelectedSkill}
            />
          )}
        </AnimatePresence>
      </main>

      <AnimatePresence>
        {selectedSkill && selectedRole && (
          <SkillActionDetailModal 
            skill={selectedSkill} 
            role={selectedRole} 
            onClose={() => setSelectedSkill(null)} 
          />
        )}
      </AnimatePresence>
    </div>
  );
};

